let rounds = try Integer.parse(arguments.get(0) ?? "10000000")
mutable values: GrowingArray<Integer> = []
for i in 0..1000000 { values.push(i) }
mutable total = 0
for i in 0..rounds {
    let index = (i * 997) %% 1000000
    total += try values[index]
}
console.log(total)
